TfLiteStatus Eval(TfLiteContext* context, TfLiteNode* node) {
  auto* params = reinterpret_cast<TfLiteSVDFParams*>(node->builtin_data);
  OpData* op_data = reinterpret_cast<OpData*>(node->user_data);

  const TfLiteTensor* input;
  TF_LITE_ENSURE_OK(context, GetInputSafe(context, node, kInputTensor, &input));
  const TfLiteTensor* weights_feature;
  TF_LITE_ENSURE_OK(context, GetInputSafe(context, node, kWeightsFeatureTensor,
                                          &weights_feature));
  const TfLiteTensor* weights_time;
  TF_LITE_ENSURE_OK(
      context, GetInputSafe(context, node, kWeightsTimeTensor, &weights_time));
  const TfLiteTensor* bias = GetOptionalInputTensor(context, node, kBiasTensor);

  TfLiteTensor* scratch;
  TF_LITE_ENSURE_OK(context,
                    GetTemporarySafe(context, node, 0, &scratch));

  TfLiteTensor* state = GetVariableInput(context, node, kStateTensor);
  TfLiteTensor* output;
  TF_LITE_ENSURE_OK(context,
                    GetOutputSafe(context, node, kOutputTensor, &output));

  switch (weights_feature->type) {
    case kTfLiteFloat32: {
      reference_ops::EvalFloatSVDF(
          params, GetTensorShape(input), GetTensorData<float>(input),
          GetTensorShape(weights_feature),
          GetTensorData<float>(weights_feature), GetTensorShape(weights_time),
          GetTensorData<float>(weights_time), GetTensorShape(bias),
          GetTensorData<float>(bias), GetTensorData<float>(scratch),
          GetTensorData<float>(state), GetTensorShape(output),
          GetTensorData<float>(output));
      return kTfLiteOk;
    }
    case kTfLiteUInt8:
    case kTfLiteInt8: {
      if (input->type == kTfLiteFloat32) {
        TfLiteTensor* input_quantized;
        TF_LITE_ENSURE_OK(context, GetTemporarySafe(context, node, 1,
                                                    &input_quantized));
        TfLiteTensor* scaling_factors;
        TF_LITE_ENSURE_OK(context, GetTemporarySafe(context, node, 2,
                                                    &scaling_factors));
        TfLiteTensor* float_weights_time;
        TF_LITE_ENSURE_OK(context, GetTemporarySafe(context, node, 3,
                                                    &float_weights_time));
        TfLiteTensor* zero_points;
        TF_LITE_ENSURE_OK(context, GetTemporarySafe(context, node, 4,
                                                    &zero_points));
        TfLiteTensor* row_sums;
        TF_LITE_ENSURE_OK(
            context, GetTemporarySafe(context, node, 5, &row_sums));
        if (!op_data->float_weights_time_initialized) {
          const float dequantization_scale = weights_time->params.scale;
          const int8_t* weights_time_ptr = GetTensorData<int8_t>(weights_time);
          float* float_weights_time_ptr =
              GetTensorData<float>(float_weights_time);
          for (int i = 0; i < NumElements(float_weights_time); ++i) {
            float_weights_time_ptr[i] =
                weights_time_ptr[i] * dequantization_scale;
          }
          op_data->float_weights_time_initialized = true;
        }

        int32_t* zero_points_ptr = nullptr;
        int32_t* row_sums_ptr = nullptr;
        if (params->asymmetric_quantize_inputs && row_sums != nullptr) {
          zero_points_ptr = GetTensorData<int32_t>(zero_points);
          row_sums_ptr = GetTensorData<int32_t>(row_sums);
        }

        reference_ops::EvalHybridSVDF(
            params, GetTensorShape(input), GetTensorData<float>(input),
            GetTensorShape(weights_feature),
            GetTensorData<int8_t>(weights_feature),
            weights_feature->params.scale, GetTensorShape(float_weights_time),
            GetTensorData<float>(float_weights_time), GetTensorShape(bias),
            GetTensorData<float>(bias), GetTensorData<float>(scratch),
            GetTensorData<float>(scaling_factors),
            GetTensorData<int8_t>(input_quantized), GetTensorData<float>(state),
            GetTensorShape(output), GetTensorData<float>(output),
            zero_points_ptr, row_sums_ptr, &op_data->compute_row_sums);
        return kTfLiteOk;
      }
      auto* input_params = reinterpret_cast<TfLiteAffineQuantization*>(
          input->quantization.params);
      auto* output_params = reinterpret_cast<TfLiteAffineQuantization*>(
          output->quantization.params);
      TfLiteTensor* output_temp;
      TF_LITE_ENSURE_OK(
          context, GetTemporarySafe(context, node, 1, &output_temp));

      TF_LITE_ENSURE_EQ(context, params->activation, kTfLiteActRelu);

      reference_ops::EvalIntegerSVDF(
          params, GetTensorShape(input), GetTensorData<int8_t>(input),
          GetTensorShape(weights_feature),
          GetTensorData<int8_t>(weights_feature), GetTensorShape(weights_time),
          GetTensorData<int16_t>(weights_time), GetTensorShape(bias),
          GetTensorData<int32_t>(bias), GetTensorData<int16_t>(state),
          GetTensorShape(output), GetTensorData<int8_t>(output),
          GetTensorData<int32_t>(scratch), GetTensorData<int32_t>(output_temp),
          op_data->effective_scale_1_a, op_data->effective_scale_1_b,
          op_data->effective_scale_2_a, op_data->effective_scale_2_b,
          input_params->zero_point->data[0],
          output_params->zero_point->data[0]);
      return kTfLiteOk;
    }
    default:
      context->ReportError(context, "Type %s not currently supported.",
                           TfLiteTypeGetName(weights_feature->type));
      return kTfLiteError;
  }
}

static int rsi_send_beacon(struct rsi_common *common)
{
	struct sk_buff *skb = NULL;
	u8 dword_align_bytes = 0;

	skb = dev_alloc_skb(MAX_MGMT_PKT_SIZE);
	if (!skb)
		return -ENOMEM;

	memset(skb->data, 0, MAX_MGMT_PKT_SIZE);

	dword_align_bytes = ((unsigned long)skb->data & 0x3f);
	if (dword_align_bytes)
		skb_pull(skb, (64 - dword_align_bytes));
	if (rsi_prepare_beacon(common, skb)) {
		rsi_dbg(ERR_ZONE, "Failed to prepare beacon\n");
		return -EINVAL;
	}
	skb_queue_tail(&common->tx_queue[MGMT_BEACON_Q], skb);
	rsi_set_event(&common->tx_thread.event);
	rsi_dbg(DATA_TX_ZONE, "%s: Added to beacon queue\n", __func__);

	return 0;
}

static int handle_pml_full(struct kvm_vcpu *vcpu)
{
	unsigned long exit_qualification;

	trace_kvm_pml_full(vcpu->vcpu_id);

	exit_qualification = vmcs_readl(EXIT_QUALIFICATION);

	if (!(to_vmx(vcpu)->idt_vectoring_info & VECTORING_INFO_VALID_MASK) &&
			cpu_has_virtual_nmis() &&
			(exit_qualification & INTR_INFO_UNBLOCK_NMI))
		vmcs_set_bits(GUEST_INTERRUPTIBILITY_INFO,
				GUEST_INTR_STATE_NMI);

	return 1;
}

void Compute(OpKernelContext* ctx) override {
  const Tensor& indices_tensor = ctx->input(0);
  OP_REQUIRES(ctx,
              TensorShapeUtils::IsVector(indices_tensor.shape()) ||
                  TensorShapeUtils::IsScalar(indices_tensor.shape()),
              errors::InvalidArgument(
                  "The indices can only be scalar or vector, got \"",
                  indices_tensor.shape().DebugString(), "\""));

  const Tensor& dims_tensor = ctx->input(1);
  OP_REQUIRES(
      ctx, TensorShapeUtils::IsVector(dims_tensor.shape()),
      errors::InvalidArgument("The indices can only be 1-D, got \"",
                              dims_tensor.shape().DebugString(), "\""));

  auto dims = dims_tensor.vec<Tidx>();

  Eigen::Tensor<Tidx, 0, Eigen::RowMajor> dims_prod_eigen = dims.prod();
  Tidx dims_prod = dims_prod_eigen();
  const Tidx* indices = indices_tensor.flat<Tidx>().data();
  int64 size = indices_tensor.NumElements();
  bool check = std::all_of(indices, indices + size,
                           [&](Tidx index) { return index < dims_prod; });
  OP_REQUIRES(ctx, check,
              errors::InvalidArgument("index is out of bound as with dims"));

  Eigen::array<bool, 1> reverse({true});

  Tensor strides_tensor;
  OP_REQUIRES_OK(ctx,
                 ctx->allocate_temp(DataTypeToEnum<Tidx>::value,
                                    TensorShape({dims_tensor.NumElements()}),
                                    &strides_tensor));

  auto strides = strides_tensor.vec<Tidx>();
  strides = dims.reverse(reverse)
                .scan(0, Eigen::internal::ProdReducer<Tidx>(), false)
                .reverse(reverse);

  Tensor strides_shifted_tensor;
  OP_REQUIRES_OK(ctx,
                 ctx->allocate_temp(DataTypeToEnum<Tidx>::value,
                                    TensorShape({dims_tensor.NumElements()}),
                                    &strides_shifted_tensor));

  auto strides_shifted = strides_shifted_tensor.vec<Tidx>();
  strides_shifted = dims.reverse(reverse)
                        .scan(0, Eigen::internal::ProdReducer<Tidx>(), true)
                        .reverse(reverse);

  Tensor* output_tensor = nullptr;
  if (TensorShapeUtils::IsScalar(indices_tensor.shape())) {
    OP_REQUIRES_OK(
        ctx, ctx->allocate_output(0, TensorShape({dims_tensor.NumElements()}),
                                  &output_tensor));

    auto output = output_tensor->vec<Tidx>();

    output = output.constant(indices_tensor.scalar<Tidx>()());
    output = output.binaryExpr(strides, mod_op<Tidx>()) / strides_shifted;
  } else {
    OP_REQUIRES_OK(
        ctx, ctx->allocate_output(0,
                                  TensorShape({dims_tensor.NumElements(),
                                               indices_tensor.NumElements()}),
                                  &output_tensor));

    auto output = output_tensor->matrix<Tidx>();

    Eigen::array<Eigen::Index, 2> reshape{
        {static_cast<Eigen::Index>(dims_tensor.NumElements()), 1}};
    Eigen::array<Eigen::Index, 2> bcast(
        {1, static_cast<Eigen::Index>(indices_tensor.NumElements())});
    Eigen::array<Eigen::Index, 2> indices_reshape{
        {1, static_cast<Eigen::Index>(indices_tensor.NumElements())}};
    Eigen::array<Eigen::Index, 2> indices_bcast(
        {static_cast<Eigen::Index>(dims_tensor.NumElements()), 1});

    output = indices_tensor.vec<Tidx>()
                 .reshape(indices_reshape)
                 .broadcast(indices_bcast);
    output = output.binaryExpr(strides.reshape(reshape).broadcast(bcast),
                               mod_op<Tidx>()) /
             strides_shifted.reshape(reshape).broadcast(bcast);
  }
}

