irc_nick_get_prefix_color_name (struct t_irc_server *server, char prefix)
{
    static char *default_color = "";
    const char *prefix_modes, *color;
    char mode[2];
    int index;

    if (irc_config_hashtable_nick_prefixes)
    {
        mode[0] = ' ';
        mode[1] = '\0';

        index = irc_server_get_prefix_char_index (server, prefix);
        if (index >= 0)
        {
            prefix_modes = irc_server_get_prefix_modes (server);
            mode[0] = prefix_modes[index];
            color = weechat_hashtable_get (irc_config_hashtable_nick_prefixes,
                                           mode);
            if (color)
                return color;
        }

        mode[0] = '*';
        color = weechat_hashtable_get (irc_config_hashtable_nick_prefixes,
                                       mode);
        if (color)
            return color;
    }

    return default_color;
}

int str2Tm(const std::string& timeStr, struct tm* tm)
{
    if (timeStr.length() == 0 || timeStr[0] == ' ')
        return 1;
    if (timeStr.length() < 19)
        return 2;
    if (timeStr[4] != ':' || timeStr[7] != ':' || timeStr[10] != ' ' || timeStr[13] != ':' || timeStr[16] != ':')
        return 3;
    if (0 == tm)
        return 4;
    std::memset(tm, 0x0, sizeof(struct tm));
    tm->tm_isdst = -1;

    long tmp;
    if (!Util::strtol(timeStr.substr(0, 4).c_str(), tmp))
        return 5;
    tm->tm_year = tmp - 1900;
    if (!Util::strtol(timeStr.substr(5, 2).c_str(), tmp))
        return 6;
    tm->tm_mon = tmp - 1;
    if (!Util::strtol(timeStr.substr(8, 2).c_str(), tmp))
        return 7;
    tm->tm_mday = tmp;
    if (!Util::strtol(timeStr.substr(11, 2).c_str(), tmp))
        return 8;
    tm->tm_hour = tmp;
    if (!Util::strtol(timeStr.substr(14, 2).c_str(), tmp))
        return 9;
    tm->tm_min = tmp;
    if (!Util::strtol(timeStr.substr(17, 2).c_str(), tmp))
        return 10;
    tm->tm_sec = tmp;

    if (mktime(tm) == (time_t)-1)
        return 11;

    return 0;
}

__switch_to(struct task_struct *prev_p, struct task_struct *next_p)
{
	struct thread_struct *prev = &prev_p->thread;
	struct thread_struct *next = &next_p->thread;
	int cpu = smp_processor_id();
	struct tss_struct *tss = &per_cpu(init_tss, cpu);
	unsigned fsindex, gsindex;
	fpu_switch_t fpu;

 	fpu = switch_fpu_prepare(prev_p, next_p, cpu);

 	load_sp0(tss, next);

	savesegment(es, prev->es);
	if (unlikely(next->es | prev->es))
		loadsegment(es, next->es);
	savesegment(ds, prev->ds);
	if (unlikely(next->ds | prev->ds))
		loadsegment(ds, next->ds);
 	savesegment(fs, fsindex);
 	savesegment(gs, gsindex);

 	load_TLS(next, cpu);

 	arch_end_context_switch(next_p);

 	if (unlikely(fsindex | next->fsindex | prev->fs)) {
 		loadsegment(fs, next->fsindex);
 		if (fsindex)
 			prev->fs = 0;
 	}
 	if (next->fs)
 		wrmsrl(MSR_FS_BASE, next->fs);
 	prev->fsindex = fsindex;

 	if (unlikely(gsindex | next->gsindex | prev->gs)) {
 		load_gs_index(next->gsindex);
 		if (gsindex)
 			prev->gs = 0;
 	}
	if (next->gs)
		wrmsrl(MSR_KERNEL_GS_BASE, next->gs);
	prev->gsindex = gsindex;

	switch_fpu_finish(next_p, fpu);

	prev->usersp = this_cpu_read(old_rsp);
	this_cpu_write(old_rsp, next->usersp);
	this_cpu_write(current_task, next_p);

	task_thread_info(prev_p)->saved_preempt_count = this_cpu_read(__preempt_count);
	this_cpu_write(__preempt_count, task_thread_info(next_p)->saved_preempt_count);

	this_cpu_write(kernel_stack,
		  (unsigned long)task_stack_page(next_p) +
		  THREAD_SIZE - KERNEL_STACK_OFFSET);

	if (unlikely(task_thread_info(next_p)->flags & _TIF_WORK_CTXSW_NEXT ||
		     task_thread_info(prev_p)->flags & _TIF_WORK_CTXSW_PREV))
		__switch_to_xtra(prev_p, next_p, tss);

	return prev_p;
}

